// Collapse the per-currency results into one item.
//
// The fetch and store nodes run once per currency; the attach step must run
// exactly once. Without this the UPDATE would fire four times - idempotent, but
// it would report four partial counts instead of one true one.

const batch = $('Open FX Sync Run').first().json;
const results = $input.all().map((item) => item.json);

if (results.length === 0) {
  throw new Error('No currency results reached the summariser - the fetch produced nothing');
}

const total = (field) =>
  results.reduce((sum, row) => sum + (Number(row[field]) || 0), 0);

return [{
  json: {
    batch_id: batch.batch_id,
    window_from: batch.window_from,
    window_to: batch.window_to,
    currencies_synced: results.length,
    rates_received: total('rates_received'),
    rates_inserted: total('rates_inserted'),
    per_currency: results.map((r) => `${r.currency}:${r.rates_received}`).join(' '),
  },
}];
